package com.vectora.api;
import io.swagger.v3.oas.models.OpenAPI; import io.swagger.v3.oas.models.Components; import io.swagger.v3.oas.models.info.Info; import io.swagger.v3.oas.models.security.SecurityScheme; import org.springframework.context.annotation.*;
@Configuration public class OpenApiConfig { @Bean OpenAPI api(){return new OpenAPI().info(new Info().title("Vectora Operations API").version("1.0.0").description("Camera, proximity sensor and drone operations API")).components(new Components().addSecuritySchemes("basicAuth",new SecurityScheme().type(SecurityScheme.Type.HTTP).scheme("basic")));} }
